It was fixing the promo code validation function. Make sure to read the documentation of function properly. 
```
async function validatePromoCode(promo, {
  eventId,
  quantity,
}) {
  const now = new Date();

  if (!promo || promo.deletedAt || promo.isDeleted) {
    throw new Error("Invalid promo code");
  }

  if (promo.startDate && now < new Date(promo.startDate)) {
    throw new Error("Promo code is not active yet");
  }

  if (promo.endDate && now > new Date(promo.endDate)) {
    throw new Error("Promo code has expired");
  }

  if (
    promo.maxUses != null &&
    promo.usedCount >= promo.maxUses
  ) {
    throw new Error("Promo code usage limit reached");
  }

  if (
    promo.eventId != null &&
    String(promo.eventId) !== String(eventId)
  ) {
    throw new Error("Promo code is not valid for this event");
  }

  if (quantity < (promo.minQuantity ?? 1)) {
    throw new Error("Minimum ticket quantity not met");
  }

  return { valid:true, promo};
}
```
